INSERT INTO `tb_materi` VALUES (1,'Semester 1',1,1,'Expression of Greeting & Parting','Mempelajari ungkapan menyapa (greeting) saat bertemu seseorang dan ungkapan berpamitan (parting) secara formal maupun informal.','<header>\r\n  <h2>MODUL PEMBELAJARAN BAHASA INGGRIS KELAS 7 SMP</h2>\r\n  <p><b>Topik:</b> Expressions of Greeting and Parting (Leave-Taking)<br>\r\n  <b>Alokasi Waktu:</b> 2 Pertemuan (4 x 40 Menit)<br>\r\n  <b>Fase / Semester:</b> Fase D / Ganjil</p>\r\n</header>\r\n\r\n<hr>\r\n\r\n<h3>1. Tujuan Pembelajaran</h3>\r\n<p>Setelah mempelajari modul ini, peserta didik diharapkan mampu:</p>\r\n<ul>\r\n  <li>Mengidentifikasi fungsi sosial, struktur teks, dan unsur kebahasaan dari ungkapan menyapa (<i>greeting</i>) dan berpamitan (<i>parting/leave-taking</i>).</li>\r\n  <li>Membedakan penggunaan ragam formal (resmi/sopan) dan informal (santai/akrab) berdasarkan lawan bicara dan situasi.</li>\r\n  <li>Menyusun kalimat serta merespons sapaan dan pamitan dengan tata bahasa, intonasi, dan pelafalan yang tepat.</li>\r\n  <li>Mempraktikkan percakapan transaksional dan interpersonal pendek secara lisan maupun tertulis dalam konteks kehidupan sehari-hari.</li>\r\n</ul>\r\n\r\n<h3>2. Definisi & Konsep Dasar</h3>\r\n<p><b>A. Definition of Greeting:</b><br>\r\n<i>Greeting</i> adalah ungkapan yang diucapkan untuk menyapa seseorang ketika baru bertemu atau memulai interaksi. Menyapa bertujuan untuk menunjukkan kesopanan, keramahan, serta membuka saluran komunikasi yang baik.</p>\r\n\r\n<p><b>B. Definition of Parting (Leave-Taking):</b><br>\r\n<i>Parting</i> atau <i>leave-taking</i> adalah ungkapan yang digunakan ketika seseorang hendak mengakhiri percakapan atau berpisah dari lawan bicara. Ungkapan ini bertujuan menutup pembicaraan dengan sopan dan memberi kesan menyenangkan.</p>\r\n\r\n<h3>3. Rumus & Pola Kalimat (Formula & Structures)</h3>\r\n<p>Untuk membentuk interaksi yang natural, gunakan rumus dasar struktur percakapan berikut:</p>\r\n\r\n<table border=\"1\" cellpadding=\"6\" cellspacing=\"0\">\r\n  <tr>\r\n    <th>Jenis Pola</th>\r\n    <th>Rumus / Formula</th>\r\n    <th>Contoh Penerapan</th>\r\n  </tr>\r\n  <tr>\r\n    <td><b>Pola Sapaan Bertingkat</b></td>\r\n    <td><i>[Salutation/Greeting] + [Name/Title] + [Asking Condition]?</i></td>\r\n    <td>\"Good morning, Mr. Hadi. How are you doing?\"</td>\r\n  </tr>\r\n  <tr>\r\n    <td><b>Pola Respons Sapaan</b></td>\r\n    <td><i>[Greeting Response] + [Condition Response] + [Gratitude] + [Return Question]?</i></td>\r\n    <td>\"Good morning! I am very well, thank you. And you?\"</td>\r\n  </tr>\r\n  <tr>\r\n    <td><b>Pola Berpamitan (Parting)</b></td>\r\n    <td><i>[Pre-closing Reason] + [Leave-taking Expression] + [Wishes/Follow-up]</i></td>\r\n    <td>\"I have to go now. Goodbye, see you tomorrow!\"</td>\r\n  </tr>\r\n  <tr>\r\n    <td><b>Pola Respons Pamitan</b></td>\r\n    <td><i>[Parting Response] + [Care/Safety Expression]</i></td>\r\n    <td>\"Goodbye! Take care on your way home.\"</td>\r\n  </tr>\r\n</table>\r\n\r\n<h3>4. Penjelasan Mendalam & Pembagian Waktu (In-Depth Explanation)</h3>\r\n\r\n<p><b>A. Formal vs. Informal Context:</b></p>\r\n<ul>\r\n  <li><b>Formal:</b> Digunakan kepada orang yang lebih tua, guru, kepala sekolah, orang asing, atau dalam suasana formal (upacara, kelas, rapat). Mengutamakan rasa hormat dan kesantunan.</li>\r\n  <li><b>Informal:</b> Digunakan kepada teman sebaya, sahabat dekat, anggota keluarga, atau dalam suasana santai (waktu istirahat, bermain, nongkrong).</li>\r\n</ul>\r\n\r\n<p><b>B. Aturan Penunjuk Waktu Sapaan Formal Bahasa Inggris:</b></p>\r\n<ul>\r\n  <li><b>Good morning:</b> Digunakan sejak pukul 00.01 tengah malam hingga pukul 11.59 siang.</li>\r\n  <li><b>Good afternoon:</b> Digunakan sejak pukul 12.00 siang hingga matahari terbenam (sekitar pukul 17.59 / 18.00 sore).</li>\r\n  <li><b>Good evening:</b> Digunakan saat bertemu orang lain pada malam hari (mulai pukul 18.00 sampai larut malam). <i>Catatan:</i> \"Good evening\" adalah sapaan bertemu, bukan pamitan!</li>\r\n  <li><b>Good night:</b> <u>Bukan</u> sapaan bertemu! \"Good night\" hanya diucapkan sebagai ungkapan pamitan (parting) saat hendak berpisah di malam hari atau ketika hendak pergi tidur.</li>\r\n</ul>\r\n\r\n<h3>5. Daftar Ungkapan Lengkap (Expressions & Responses)</h3>\r\n\r\n<p><b>A. Expressions of Greeting:</b></p>\r\n<table border=\"1\" cellpadding=\"6\" cellspacing=\"0\">\r\n  <tr>\r\n    <th>Kategori</th>\r\n    <th>Expression (Ungkapan)</th>\r\n    <th>Meaning (Arti)</th>\r\n    <th>Responses (Tanggapan)</th>\r\n  </tr>\r\n  <tr>\r\n    <td rowspan=\"4\"><b>Formal</b></td>\r\n    <td>Good morning / afternoon / evening</td>\r\n    <td>Selamat pagi / siang-sore / malam</td>\r\n    <td>Good morning / afternoon / evening</td>\r\n  </tr>\r\n  <tr>\r\n    <td>How do you do? <i>(Khusus pertemuan pertama)</i></td>\r\n    <td>Apa kabar? / Salam kenal</td>\r\n    <td>How do you do?</td>\r\n  </tr>\r\n  <tr>\r\n    <td>How are you?</td>\r\n    <td>Bagaimana kabar Anda?</td>\r\n    <td>I am fine / I am very well, thank you.</td>\r\n  </tr>\r\n  <tr>\r\n    <td>It is a pleasure to meet you.</td>\r\n    <td>Senang bertemu dengan Anda.</td>\r\n    <td>Pleasure to meet you too.</td>\r\n  </tr>\r\n  <tr>\r\n    <td rowspan=\"5\"><b>Informal</b></td>\r\n    <td>Hi! / Hello!</td>\r\n    <td>Hai! / Halo!</td>\r\n    <td>Hello! / Hi!</td>\r\n  </tr>\r\n  <tr>\r\n    <td>How are you doing?</td>\r\n    <td>Bagaimana kabarmu?</td>\r\n    <td>I\'m great! / Not bad!</td>\r\n  </tr>\r\n  <tr>\r\n    <td>How\'s life? / How are things?</td>\r\n    <td>Gimana kabarnya?</td>\r\n    <td>Pretty good / Everything is fine.</td>\r\n  </tr>\r\n  <tr>\r\n    <td>What\'s up?</td>\r\n    <td>Ada apa? / Apa kabar?</td>\r\n    <td>Nothing much / Just chilling.</td>\r\n  </tr>\r\n  <tr>\r\n    <td>Nice to meet you!</td>\r\n    <td>Senang bertemu denganmu!</td>\r\n    <td>Nice to meet you too!</td>\r\n  </tr>\r\n</table>\r\n\r\n<p><b>B. Expressions of Parting / Leave-Taking:</b></p>\r\n<table border=\"1\" cellpadding=\"6\" cellspacing=\"0\">\r\n  <tr>\r\n    <th>Kategori</th>\r\n    <th>Expression (Ungkapan)</th>\r\n    <th>Meaning (Arti)</th>\r\n    <th>Responses (Tanggapan)</th>\r\n  </tr>\r\n  <tr>\r\n    <td rowspan=\"3\"><b>Formal</b></td>\r\n    <td>Goodbye, Sir/Ma\'am.</td>\r\n    <td>Selamat tinggal, Pak/Bu.</td>\r\n    <td>Goodbye, have a good day.</td>\r\n  </tr>\r\n  <tr>\r\n    <td>Good night.</td>\r\n    <td>Selamat tidur / Selamat malam (pisah).</td>\r\n    <td>Good night, have a nice dream.</td>\r\n  </tr>\r\n  <tr>\r\n    <td>It was nice meeting you.</td>\r\n    <td>Senang bisa bertemu dengan Anda.</td>\r\n    <td>It was nice meeting you too.</td>\r\n  </tr>\r\n  <tr>\r\n    <td rowspan=\"5\"><b>Informal</b></td>\r\n    <td>Bye! / Bye-bye!</td>\r\n    <td>Dah! / Sampai jumpa!</td>\r\n    <td>Bye! / See ya!</td>\r\n  </tr>\r\n  <tr>\r\n    <td>See you later / See you soon!</td>\r\n    <td>Sampai jumpa nanti / segera!</td>\r\n    <td>See you!</td>\r\n  </tr>\r\n  <tr>\r\n    <td>See you tomorrow!</td>\r\n    <td>Sampai jumpa besok!</td>\r\n    <td>See you tomorrow!</td>\r\n  </tr>\r\n  <tr>\r\n    <td>I must get going now.</td>\r\n    <td>Aku harus cabut/pergi sekarang.</td>\r\n    <td>Sure, catch you later!</td>\r\n  </tr>\r\n  <tr>\r\n    <td>Take care!</td>\r\n    <td>Hati-hati di jalan ya!</td>\r\n    <td>You too! / Thanks!</td>\r\n  </tr>\r\n</table>\r\n\r\n<h3>6. Contoh Percakapan (Dialogues in Action)</h3>\r\n\r\n<p><b>Dialogue 1: Formal Setting (Antara Siswa dan Guru di Sekolah)</b><br>\r\n<i>Situasi: Dodi berpapasan dengan Ibu Ratna, guru Bahasa Inggris, di koridor perpustakaan sekolah pada pukul 07.15 pagi.</i></p>\r\n<p>\r\n<b>Dodi:</b> \"Good morning, Mrs. Ratna. How are you this morning?\"<br>\r\n<b>Mrs. Ratna:</b> \"Good morning, Dodi. I am doing very well, thank you. You look fresh today, how about you?\"<br>\r\n<b>Dodi:</b> \"I am wonderful, thank you Ma\'am. Are you going to the library?\"<br>\r\n<b>Mrs. Ratna:</b> \"Yes, I need to return some textbooks before the bell rings.\"<br>\r\n<b>Dodi:</b> \"Alright, Ma\'am. The bell is ringing, so I have to go to my class now. Goodbye, Mrs. Ratna!\"<br>\r\n<b>Mrs. Ratna:</b> \"Goodbye, Dodi. Have a great study today!\"<br>\r\n<b>Dodi:</b> \"Thank you, Ma\'am. See you later!\"\r\n</p>\r\n\r\n<p><b>Dialogue 2: Informal Setting (Antara Dua Orang Sahabat)</b><br>\r\n<i>Situasi: Rian dan Kevin bertemu di kantin sekolah saat jam istirahat siang.</i></p>\r\n<p>\r\n<b>Kevin:</b> \"Hey, Rian! What\'s up, bro?\"<br>\r\n<b>Rian:</b> \"Hi, Kev! Pretty good, just a bit tired after PE class. How are things with you?\"<br>\r\n<b>Kevin:</b> \"Never better! Look at my new football jersey. Do you want to play soccer at the field this afternoon?\"<br>\r\n<b>Rian:</b> \"That sounds awesome! Let\'s meet at 4 p.m.\"<br>\r\n<b>Kevin:</b> \"Deal. Oh, my sister is calling me, I\'ve got to run.\"<br>\r\n<b>Rian:</b> \"Okay, no problem. Catch you later, Kev!\"<br>\r\n<b>Kevin:</b> \"See ya later, Rian! Take care!\"\r\n</p>\r\n\r\n<p><b>Dialogue 3: Night Situation (Perpisahan Malam Hari)</b><br>\r\n<i>Situasi: Maya sedang belajar kelompok di rumah Nita hingga pukul 20.30 malam.</i></p>\r\n<p>\r\n<b>Maya:</b> \"Nita, our science project is finally done. It\'s almost 9 o\'clock, my father is waiting outside.\"<br>\r\n<b>Nita:</b> \"Thank you so much for your help today, Maya.\"<br>\r\n<b>Maya:</b> \"Don\'t mention it! Good night, Nita. See you tomorrow at school.\"<br>\r\n<b>Nita:</b> \"Good night, Maya. Take care on the road and have sweet dreams!\"\r\n</p>\r\n\r\n<h3>7. Catatan Penting & Kesalahan Umum (Common Mistakes)</h3>\r\n<ul>\r\n  <li><b>Salah:</b> Mengucapkan <i>\"Good night!\"</i> saat baru bertemu teman di malam hari pada jam 19.00.<br>\r\n  <b>Benar:</b> Ucapkan <i>\"Good evening!\"</i> saat bertemu, lalu ucapkan <i>\"Good night!\"</i> hanya ketika hendak pulang atau tidur.</li>\r\n  <li><b>Salah:</b> Menjawab <i>\"How do you do?\"</i> dengan jawaban <i>\"I am fine, thank you.\"</i><br>\r\n  <b>Benar:</b> <i>\"How do you do?\"</i> adalah sapaan formal saat pertama kali berkenalan, sehingga respons yang baku dan tepat adalah kembali menjawab: <i>\"How do you do?\"</i></li>\r\n  <li><b>Salah:</b> Menulis pemisahan kata yang salah seperti <i>\"Good bye\"</i> menjadi satu huruf yang rancu, atau melupakan tanda seru/tanya pada ekspresi sapaan.</li>\r\n</ul>\r\n\r\n<h3>8. Kosakata Kunci (Vocabulary Focus)</h3>\r\n<ul>\r\n  <li><b>Greeting:</b> Sapaan / Ucapan salam saat bertemu</li>\r\n  <li><b>Parting / Leave-taking:</b> Ungkapan berpamitan / Perpisahan</li>\r\n  <li><b>Response:</b> Respons / Tanggapan / Balasan</li>\r\n  <li><b>Salutation:</b> Salam pembuka</li>\r\n  <li><b>Pre-closing:</b> Ungkapan pendahulu sebelum mengakhiri obrolan (misal: <i>\"I have to go now\"</i>)</li>\r\n  <li><b>Polite / Courteous:</b> Sopan / Santun</li>\r\n  <li><b>Peers:</b> Teman sebaya</li>\r\n  <li><b>Take care:</b> Hati-hati / Jaga diri</li>\r\n</ul>\r\n\r\n<h3>9. Latihan Soal Pemahaman (Mini Exercises)</h3>\r\n<p><b>A. Lengkapi dialog rumpang di bawah ini:</b></p>\r\n<ol>\r\n  <li>Rani: \"Good afternoon, Mr. Joko.\"<br>\r\n      Mr. Joko: \"..., Rani. Where are you going?\"<br>\r\n      <i>Jawaban: ____________________</i></li>\r\n  <li>Dimas: \"It is getting late. I have to go home now. Good night, Fajar!\"<br>\r\n      Fajar: \"..., Dimas. Sweet dreams!\"<br>\r\n      <i>Jawaban: ____________________</i></li>\r\n  <li>Sarah: \"Hi, Tiara! How are you doing?\"<br>\r\n      Tiara: \"..., thanks. And you?\"<br>\r\n      <i>Jawaban: ____________________</i></li>\r\n</ol>\r\n\r\n<p><b>B. Pertanyaan Benar/Salah (True or False):</b></p>\r\n<ol>\r\n  <li>We say \"Good night\" to greet someone when we meet them at 7:00 PM. (<b>True / False</b>)</li>\r\n  <li>\"What\'s up?\" is an informal greeting used among friends. (<b>True / False</b>)</li>\r\n  <li>The correct response to \"How do you do?\" is \"How do you do?\". (<b>True / False</b>)</li>\r\n</ol>','2026-09-14 11:56:31',NULL),(2,'Semester 1',1,2,'Expression of Thanking & Apologizing','Mempelajari cara berterima kasih (gratitude) atas bantuan seseorang dan meminta maaf (apology) saat melakukan kesalahan beserta responnya.','<h3>1. Tujuan Pembelajaran</h3>\n<p>Siswa mampu menyampaikan rasa syukur/terima kasih (thanking) dan meminta maaf (apologizing) dengan sopan dalam interaksi interpersonal di sekolah.</p>\n\n<h3>2. Uraian Materi</h3>\n<p><b>A. Expressing Gratitude (Thanking):</b></p>\n<ul>\n  <li>Thank you / Thank you very much / Thanks a lot.</li>\n  <li><b>Respon:</b> You are welcome, Don\'t mention it, My pleasure, Anytime.</li>\n</ul>\n<p><b>B. Expressing Apology (Apologizing):</b></p>\n<ul>\n  <li>I am sorry / I\'m so sorry / Please forgive me.</li>\n  <li><b>Respon:</b> That\'s okay, Never mind, It doesn\'t matter, Don\'t worry about it.</li>\n</ul>\n\n<h3>3. Contoh Percakapan</h3>\n<p><b>Dialogue:</b><br>\n<i>Siti:</i> \"I\'m really sorry, Dayu. I forgot to bring your English dictionary.\"<br>\n<i>Dayu:</i> \"Never mind, Siti. You can bring it tomorrow.\"<br>\n<i>Siti:</i> \"Thank you for understanding, Dayu!\"<br>\n<i>Dayu:</i> \"You\'re welcome.\"</p>','2026-09-14 11:56:31',NULL),(3,'Semester 1',1,3,'Vocabularies: Family','Mempelajari kosakata pohon keluarga (family tree) seperti orang tua, saudara kandung, kakek-nenek, paman, dan bibi.','<h3>1. Tujuan Pembelajaran</h3>\n<p>Siswa mengenal struktur pohon keluarga (family tree) dan mampu mendeskripsikan hubungan kekerabatan dalam bahasa Inggris.</p>\n\n<h3>2. Uraian Materi & Kosakata Keluarga</h3>\n<ul>\n  <li><b>Nuclear Family (Keluarga Inti):</b> Father (Ayah), Mother (Ibu), Parents (Orang Tua), Son (Anak Laki-laki), Daughter (Anak Perempuan), Brother (Saudara Laki-laki), Sister (Saudara Perempuan).</li>\n  <li><b>Extended Family (Keluarga Besar):</b> Grandfather (Kakek), Grandmother (Nenek), Uncle (Paman), Aunt (Bibi), Cousin (Sepupu), Nephew (Keponakan Laki-laki), Niece (Keponakan Perempuan).</li>\n</ul>\n\n<h3>3. Contoh Kalimat</h3>\n<ul>\n  <li>My father is an engineer and my mother is a teacher.</li>\n  <li>I have one older brother and two younger sisters.</li>\n  <li>Mr. Joko is my uncle; he is my father\'s younger brother.</li>\n</ul>','2026-09-14 11:56:31',NULL),(4,'Semester 1',1,4,'Introduction to Verb','Mengenal kata kerja (action verbs) dalam bahasa Inggris dan penggunaannya dalam kalimat sederhana.','<h3>1. Tujuan Pembelajaran</h3>\n<p>Memahami definisi kata kerja (verb) sebagai kata yang menyatakan aksi atau kegiatan dalam sebuah kalimat.</p>\n\n<h3>2. Uraian Materi</h3>\n<p><b>Kata Kerja Aksi (Action Verbs):</b></p>\n<ul>\n  <li>Read (Membaca), Write (Menulis), Listen (Mendengarkan), Speak (Berbicara).</li>\n  <li>Eat (Makan), Drink (Minum), Sleep (Tidur), Study (Belajar).</li>\n  <li>Run (Berlari), Walk (Berjalan), Play (Bermain), Swim (Berenang).</li>\n</ul>\n<p><b>Struktur Kalimat Sederhana:</b> Subject + Verb + Object<br>\nContoh: <i>I read a book every morning.</i></p>','2026-09-14 11:56:31',NULL),(5,'Semester 1',1,5,'Introduction to Pronoun','Mengenal kata ganti orang (Personal Pronouns) sebagai subjek dan objek serta kata ganti kepemilikan (Possessive Adjectives).','<h3>1. Tujuan Pembelajaran</h3>\n<p>Siswa mampu menggantikan kata benda (noun) dengan kata ganti (pronoun) yang tepat dalam kalimat.</p>\n\n<h3>2. Tabel Pronouns</h3>\n<table border=\'1\' cellpadding=\'6\' style=\'border-collapse: collapse; width: 100%; margin: 1rem 0;\'>\n  <tr style=\'background: #f1f5f9;\'>\n    <th>Subject Pronoun</th><th>Object Pronoun</th><th>Possessive Adjective</th><th>Arti</th>\n  </tr>\n  <tr><td>I</td><td>Me</td><td>My</td><td>Saya</td></tr>\n  <tr><td>You</td><td>You</td><td>Your</td><td>Kamu</td></tr>\n  <tr><td>We</td><td>Us</td><td>Our</td><td>Kita / Kami</td></tr>\n  <tr><td>They</td><td>Them</td><td>Their</td><td>Mereka</td></tr>\n  <tr><td>He</td><td>Him</td><td>His</td><td>Dia (Laki-laki)</td></tr>\n  <tr><td>She</td><td>Her</td><td>Her</td><td>Dia (Perempuan)</td></tr>\n  <tr><td>It</td><td>It</td><td>Its</td><td>Benda / Hewan</td></tr>\n</table>','2026-09-14 11:56:31',NULL),(6,'Semester 1',1,6,'Numbers (Cardinal & Ordinal)','Mempelajari perbedaan bilangan cacah/kuantitas (Cardinal Numbers) dan bilangan tingkat/urutan (Ordinal Numbers).','<h3>1. Tujuan Pembelajaran</h3>\n<p>Siswa dapat melafalkan dan menuliskan bilangan pokok (cardinal) serta tingkatan urutan (ordinal) dalam bahasa Inggris.</p>\n\n<h3>2. Perbedaan Bilangan</h3>\n<ul>\n  <li><b>Cardinal Numbers (Menyatakan Jumlah):</b> One (1), Two (2), Three (3), Ten (10), Twenty (20), One hundred (100).</li>\n  <li><b>Ordinal Numbers (Menyatakan Peringkat/Tanggal):</b> First (1st), Second (2nd), Third (3rd), Fourth (4th), Fifth (5th), Tenth (10th).</li>\n</ul>\n\n<h3>3. Contoh Penggunaan</h3>\n<ul>\n  <li>I have <b>three</b> pencils in my pencil case. (Jumlah)</li>\n  <li>He won the <b>first</b> prize in the English speech competition. (Urutan)</li>\n</ul>','2026-09-14 11:56:31',NULL),(7,'Semester 1',1,7,'Introduction to Date','Mempelajari nama hari, nama bulan, dan tata cara penulisan serta pembacaan tanggal dalam bahasa Inggris.','<h3>1. Tujuan Pembelajaran</h3>\n<p>Siswa mampu menyebutkan hari, bulan, dan menyatakan tanggal lahir atau momen penting dalam format penulisan resmi bahasa Inggris.</p>\n\n<h3>2. Uraian Materi</h3>\n<p><b>Days of the Week:</b> Sunday, Monday, Tuesday, Wednesday, Thursday, Friday, Saturday.<br>\n<b>Months of the Year:</b> January, February, March, April, May, June, July, August, September, October, November, December.</p>\n\n<p><b>Format Tanggal:</b></p>\n<ul>\n  <li>British English: <i>17th August 1945</i> (The seventeenth of August, nineteen forty-five).</li>\n  <li>American English: <i>August 17th, 1945</i> (August the seventeenth, nineteen forty-five).</li>\n</ul>','2026-09-14 11:56:31',NULL),(8,'Semester 1',1,8,'Introduction to Time','Mempelajari cara menanyakan waktu dan membaca jam menggunakan pola O\'clock, Half past, Quarter past, dan Quarter to.','<h3>1. Tujuan Pembelajaran</h3>\n<p>Siswa mampu menanyakan waktu (telling time) dan membaca jam dengan pola standar internasional.</p>\n\n<h3>2. Pola Membaca Jam</h3>\n<ul>\n  <li><b>Tepat:</b> It is ... o\'clock (Contoh: 07.00 = It is seven o\'clock).</li>\n  <li><b>Lewat 15 Menit:</b> A quarter past ... (Contoh: 07.15 = It is a quarter past seven).</li>\n  <li><b>Lewat 30 Menit:</b> A half past ... (Contoh: 07.30 = It is a half past seven).</li>\n  <li><b>Kurang 15 Menit:</b> A quarter to ... (Contoh: 07.45 = It is a quarter to eight).</li>\n</ul>','2026-09-14 11:56:31',NULL),(9,'Semester 1',1,9,'Preposition of Time (In, On, At)','Mempelajari aturan penggunaan kata depan waktu: AT untuk jam spesifik, ON untuk hari dan tanggal, IN untuk bulan, tahun, dan musim.','<h3>1. Aturan Penggunaan Preposition of Time</h3>\n<ul>\n  <li><b>AT (Waktu Spesifik/Jam):</b> at 7 o\'clock, at noon, at night, at midnight.</li>\n  <li><b>ON (Hari & Tanggal Tertentu):</b> on Monday, on Friday, on August 17th, on my birthday.</li>\n  <li><b>IN (Periode Panjang: Bulan, Tahun, Abad):</b> in the morning, in July, in 2026, in summer.</li>\n</ul>\n\n<h3>2. Contoh Kalimat</h3>\n<ul>\n  <li>We go to school <b>at</b> 06:45 AM.</li>\n  <li>We have an English flag ceremony <b>on</b> Monday.</li>\n  <li>SMP Swasta Nommensen was founded <b>in</b> 1985.</li>\n</ul>','2026-09-14 11:56:31',NULL),(10,'Semester 2',2,10,'Vocabularies: Tools, Creatures, and Places','Mempelajari kosakata benda/peralatan sehari-hari (tools), makhluk hidup/hewan (creatures), dan tempat umum (public places).','<h3>1. Pengelompokan Kosakata</h3>\n<ul>\n  <li><b>Tools & Objects:</b> Scissors (Gunting), Hammer (Palu), Broom (Sapu), Ruler (Penggaris).</li>\n  <li><b>Creatures (Makhluk Hidup):</b> Butterfly (Kupu-kupu), Eagle (Elang), Whale (Paus), Rabbit (Kelinci).</li>\n  <li><b>Places (Tempat Umum):</b> Hospital (Rumah Sakit), Library (Perpustakaan), Market (Pasar), School yard (Halaman Sekolah).</li>\n</ul>','2026-09-14 11:56:31',NULL),(11,'Semester 2',2,11,'Introduction to Noun','Mengenal kata benda (Noun), perbedaan Countable Nouns (dapat dihitung) dan Uncountable Nouns (tidak dapat dihitung), serta bentuk jamak (plural).','<h3>1. Klasifikasi Kata Benda (Noun)</h3>\n<ul>\n  <li><b>Countable Noun (Bisa Dihitung):</b> Book -> Books, Pen -> Pens, Student -> Students. Memiliki bentuk singular dan plural (-s/-es).</li>\n  <li><b>Uncountable Noun (Tidak Bisa Dihitung):</b> Water, Sugar, Milk, Rice, Money, Information. Tidak ditambahkan akhiran -s.</li>\n</ul>','2026-09-14 11:56:31',NULL),(12,'Semester 2',2,12,'How Many vs How Much','Mempelajari penggunaan \"How many\" untuk kata benda yang dapat dihitung (countable) dan \"How much\" untuk yang tidak dapat dihitung serta menanyakan harga.','<h3>1. Kaidah Penggunaan How Many & How Much</h3>\n<ul>\n  <li><b>How Many + Plural Countable Noun:</b><br>\n  Contoh: <i>How many pencils do you have?</i> / <i>How many students are in the room?</i></li>\n  <li><b>How Much + Uncountable Noun:</b><br>\n  Contoh: <i>How much water do you drink a day?</i> / <i>How much sugar do we need?</i></li>\n  <li><b>How Much (Menanyakan Harga):</b><br>\n  Contoh: <i>How much is this book? It is Rp 25.000.</i></li>\n</ul>','2026-09-14 11:56:31',NULL),(13,'Semester 2',2,13,'Articles (A, An, The)','Mempelajari kata sandang A, AN (Indefinite Articles) berdasarkan bunyi vokal/konsonan dan THE (Definite Article) untuk benda yang sudah spesifik.','<h3>1. Aturan Penggunaan Articles</h3>\n<ul>\n  <li><b>A:</b> Digunakan sebelum kata benda berbunyi konsonan. (a book, a cat, a university -> bunyi \'yu\').</li>\n  <li><b>AN:</b> Digunakan sebelum kata benda berbunyi vokal (A, I, U, E, O). (an apple, an eraser, an hour -> bunyi \'our\').</li>\n  <li><b>THE:</b> Digunakan untuk benda spesifik yang sudah diketahui oleh pembicara dan pendengar. (The sun, the teacher).</li>\n</ul>','2026-09-14 11:56:31',NULL),(14,'Semester 2',2,14,'Preposition of Place','Mempelajari kata depan penunjuk lokasi/posisi benda seperti in, on, under, beside, between, behind, dan in front of.','<h3>1. Macam-Macam Preposition of Place</h3>\n<ul>\n  <li><b>In:</b> Di dalam (The pen is in the pencil case).</li>\n  <li><b>On:</b> Di atas menempel (The book is on the desk).</li>\n  <li><b>Under:</b> Di bawah (The cat is sleeping under the table).</li>\n  <li><b>Between:</b> Di antara dua benda (The library is between the lab and the canteen).</li>\n  <li><b>Behind:</b> Di belakang (The whiteboard is behind the teacher).</li>\n  <li><b>In front of:</b> Di depan (The teacher stands in front of the class).</li>\n</ul>','2026-09-14 11:56:31',NULL),(15,'Semester 2',2,15,'Aspects of Descriptive Text','Mempelajari struktur teks deskriptif: Identification (pengenalan objek) dan Description (penjelasan ciri fisik/sifat) beserta unsur kebahasaannya.','<h3>1. Tujuan Teks Deskriptif</h3>\n<p>Mendeskripsikan orang, hewan, benda, atau tempat tertentu secara detail dan jelas.</p>\n\n<h3>2. Struktur Generik (Generic Structure)</h3>\n<ul>\n  <li><b>Identification:</b> Bagian pembuka yang mengenalkan objek yang akan dideskripsikan (Who/What).</li>\n  <li><b>Description:</b> Menjelaskan bagian-bagian, ciri fisik, warna, ukuran, sifat, atau perilaku khas objek tersebut.</li>\n</ul>\n\n<h3>3. Ciri Kebahasaan</h3>\n<ul>\n  <li>Menggunakan Simple Present Tense.</li>\n  <li>Banyak menggunakan kata sifat (Adjectives): big, friendly, tall, green.</li>\n</ul>','2026-09-14 11:56:31',NULL),(16,'Semester 2',2,16,'Expression of Asking and Describing','Mempelajari cara menanyakan penampilan fisik/sifat seseorang (\"What does he look like?\") dan memberikan deskripsi yang tepat.','<h3>1. Pertanyaan Menanyakan Ciri & Sifat</h3>\n<ul>\n  <li><b>Penampilan Fisik:</b> \"What does she look like?\" -> She is tall and has long curly hair.</li>\n  <li><b>Sifat / Karakter:</b> \"What is he like?\" -> He is very kind, polite, and humorous.</li>\n  <li><b>Benda:</b> \"What does your bag look like?\" -> It is blue with two zipper pockets.</li>\n</ul>','2026-09-14 11:56:31',NULL),(17,'Semester 2',2,17,'Introduction to Adjective','Mengenal kata sifat (Adjective) yang mendeskripsikan kondisi, ukuran, warna, bentuk, dan perasaan manusia atau karakteristik benda.','<h3>1. Definisi & Kategori Kata Sifat (Adjective)</h3>\n<p>Kata sifat digunakan untuk memberikan keterangan kualitas atau kuantitas pada kata benda (noun).</p>\n<ul>\n  <li><b>Ukuran/Dimensi:</b> Big, Small, Tall, Short, Wide.</li>\n  <li><b>Warna:</b> Red, Blue, White, Black, Yellow.</li>\n  <li><b>Perasaan/Emosi:</b> Happy, Sad, Tired, Excited, Proud.</li>\n  <li><b>Kualitas/Sifat:</b> Diligent, Smart, Friendly, Helpful, Honest.</li>\n</ul>','2026-09-14 11:56:31',NULL),(18,'Semester 2',2,18,'Introduction of Simple Present Tense','Mempelajari pembentukan kalimat Simple Present Tense untuk kebiasaan sehari-hari (habit) dan fakta umum dengan subjek tunggal/jamak.','<h3>1. Rumus Simple Present Tense</h3>\n<ul>\n  <li><b>Kalimat Positif (+):</b><br>\n  - I / You / We / They + V1 (Contoh: They study English every day).<br>\n  - He / She / It + V1 + s/es (Contoh: She studies English every day).</li>\n  <li><b>Kalimat Negatif (-):</b><br>\n  - I / You / We / They + do not + V1.<br>\n  - He / She / It + does not + V1.</li>\n  <li><b>Kalimat Tanya (?):</b><br>\n  - Do/Does + Subject + V1?</li>\n</ul>','2026-09-14 11:56:31',NULL),(19,'Semester 2',2,19,'Contextual Meaning of Songs','Memahami pesan moral, makna kontekstual, dan nilai-nilai inspiratif yang terkandung dalam lirik lagu bahasa Inggris.','<h3>1. Tujuan Pembelajaran</h3>\n<p>Siswa mampu mengidentifikasi fungsi sosial, tema, dan pesan moral (moral message/values) yang disampaikan oleh penulis melalui lirik lagu berbahasa Inggris.</p>\n\n<h3>2. Unsur dalam Lagu</h3>\n<ul>\n  <li><b>Theme (Tema):</b> Friendship (Persahabatan), Love, Motivation, Family, Nature.</li>\n  <li><b>Moral Message:</b> Nasehat atau nilai positif yang dapat dipetik pendengar (Contoh: Never give up on your dreams, appreciate your true friends).</li>\n  <li><b>Rhyme & Rhythm:</b> Rima sajak dan irama nada yang membuat lagu berkesan.</li>\n</ul>','2026-09-14 11:56:31',NULL),(20,'Semester 2',2,20,'Expression of Liking and Dislike','Mempelajari cara menyatakan kesukaan (like/love/enjoy/fond of) dan ketidaksukaan (dislike/hate/don\'t like) terhadap aktivitas atau hobi.','<h3>1. Ungkapan Menyatakan Kesukaan (Expressing Like)</h3>\n<ul>\n  <li>I like / I love playing badminton.</li>\n  <li>I really enjoy reading adventure novels.</li>\n  <li>She is fond of singing English pop songs.</li>\n</ul>\n\n<h3>2. Ungkapan Menyatakan Ketidaksukaan (Expressing Dislike)</h3>\n<ul>\n  <li>I dislike / I don\'t like eating spicy noodles.</li>\n  <li>He hates getting stuck in traffic jams.</li>\n  <li>I can\'t stand noisy environments when studying.</li>\n</ul>','2026-09-14 11:56:31',NULL);
